revision.text:
/* Template:Note/styles.css: notes and "Main article" lines (TemplateStyles). */
.rp-hatnote {
	margin: 0.4em 0 0.8em;
	padding-left: 1.6em;
	font-style: italic;
	opacity: 0.85;
}
.rp-box-note {
	margin: 0.6rem 0 0.8rem;
	padding: 10px 15px;
	border-left: 4px solid rgba( 59, 130, 246, 0.8 );
	border-radius: 8px;
	background: rgba( 59, 130, 246, 0.1 );
	font-size: 0.875rem;
	line-height: 1.4;
}
